package net.officefloor.hq.app.access;

import java.util.EnumSet;
import java.util.Set;

/**
 * An action the sheet's permission matrix governs, with the roles that may take it when the matrix leaves
 * it blank (the standing rule): open, settle, void and close by clerk and steward; reassign and reopen by
 * steward. Its setting key is perm-&lt;action&gt;, its value a comma separated list of roles.
 */
public enum Permission {
    OPEN(EnumSet.of(Role.CLERK, Role.STEWARD)),
    SETTLE(EnumSet.of(Role.CLERK, Role.STEWARD)),
    VOID(EnumSet.of(Role.CLERK, Role.STEWARD)),
    REASSIGN(EnumSet.of(Role.STEWARD)),
    CLOSE(EnumSet.of(Role.CLERK, Role.STEWARD)),
    REOPEN(EnumSet.of(Role.STEWARD));

    /** A permission value as written: blank, or roles separated by commas. */
    public static final String ROLES = "(\\s*(clerk|steward)\\s*(,\\s*(clerk|steward)\\s*)*)?";

    private final Set<Role> standing;

    Permission(Set<Role> standing) {
        this.standing = standing;
    }

    /** The action as it is written: lower case. */
    public String action() {
        return name().toLowerCase();
    }

    /** The setting key: perm-&lt;action&gt;. */
    public String key() {
        return "perm-" + action();
    }

    /** Whether the role may take the action under the value set (null or blank: the standing rule). */
    public boolean allows(String value, Role role) {
        if (value == null || value.isBlank()) {
            return standing.contains(role);
        }
        for (String r : value.split(",")) {
            if (r.trim().equals(role.key())) {
                return true;
            }
        }
        return false;
    }
}
package net.officefloor.hq.app.access;

import java.util.Arrays;
import java.util.Optional;

/**
 * What a user may do on a sheet: a clerk settles only within the clerk limit (above it the claim goes
 * PENDING), a steward settles anything and approves or rejects a PENDING claim; a viewer sees everything
 * and can change nothing.
 */
public enum Role {
    CLERK, STEWARD, VIEWER;

    /** The role as it is written: lower case. */
    public String key() {
        return name().toLowerCase();
    }

    public static Optional<Role> of(String key) {
        return Arrays.stream(values()).filter(r -> r.key().equals(key)).findFirst();
    }
}
package net.officefloor.hq.app.access;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import org.springframework.http.HttpMethod;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;

/**
 * Refuses every change a viewer asks for on a sheet, and every change anyone asks for on an archived sheet
 * (403, writing nothing). Reading, and loading a sheet, go through; so do the bulk actions, which answer
 * with nothing done and every selected item refused.
 */
@Component
public class ViewerGuard implements HandlerInterceptor {

    private static final String REFUSAL = "{\"message\":\"A viewer can change nothing.\"}";

    private static final String ARCHIVED = "{\"message\":\"The sheet is archived: nothing on it can change.\"}";

    private final AccessService access;

    public ViewerGuard(AccessService access) {
        this.access = access;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler)
            throws Exception {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) {
            return true;
        }
        String path = request.getRequestURI();
        if (path.endsWith("/load") || path.contains("/bulk-") || path.endsWith("/people/grade")) {
            return true;
        }
        Object vars = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        String user = request.getHeader("X-User");
        if (!(vars instanceof Map<?, ?> v) || user == null) {
            return true;
        }
        Object sheet = v.containsKey("sheetId") ? v.get("sheetId") : v.get("id");
        if (!(sheet instanceof String id)) {
            return true;
        }
        String refusal = access.isArchived(id.trim()) ? ARCHIVED
                : access.isViewer(id.trim(), user.trim()) ? REFUSAL : null;
        if (refusal == null) {
            return true;
        }
        response.setStatus(HttpStatus.FORBIDDEN.value());
        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
        response.getWriter().write(refusal);
        return false;
    }
}
