-- A claim's place in its person's list, newest first: taken when the claim is added, and taken again
-- when the claim is reassigned to another person, so it lists as that person's newest claim.
CREATE SEQUENCE claim_listed_seq;
ALTER TABLE claim ADD COLUMN listed BIGINT DEFAULT NEXT VALUE FOR claim_listed_seq NOT NULL;
-- The pools on a sheet, each name once, and their members: people of the sheet, each in a pool at most
-- once, with a share percent (more than 0.00, at most 100.00). A person can be in several pools.
CREATE TABLE pool (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(100) NOT NULL,
    CONSTRAINT pool_unique UNIQUE (sheet_id, name)
);
CREATE TABLE pool_member (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    pool_id   BIGINT NOT NULL REFERENCES pool (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    share     DECIMAL(5, 2) NOT NULL CHECK (share > 0 AND share <= 100),
    CONSTRAINT pool_member_unique UNIQUE (pool_id, person_id)
);
-- A claim bound by its person's last statement: it shows and totals the figure it had then
-- (stated_due, null when it had none) until the next statement rebinds or releases it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(14, 2);

-- The statements taken for a person, in the order taken (by id): the sheet's today then, the
-- person's due-total then (null when it was n/a) and how many of their claims counted.
CREATE TABLE statement (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100)   NOT NULL REFERENCES sheet (id),
    person_id BIGINT         NOT NULL REFERENCES person (id),
    taken_on  DATE           NOT NULL,
    due_total DECIMAL(14, 2),
    claims    INT            NOT NULL
);
CREATE INDEX statement_person ON statement (sheet_id, person_id, id);
-- The users watching a person on a sheet, each at most once, in the order they started watching (by id).
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(200) NOT NULL,
    CONSTRAINT person_watch_unique UNIQUE (person_id, user_name)
);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);
-- Each person's due-total for a closed period, fixed when it was closed, for every person on the
-- sheet then; a person added later has none (shown as 0.00). Removed when the period is reopened.
CREATE TABLE period_person_total (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    person_id BIGINT         NOT NULL,
    total     DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, person_id)
);
package net.officefloor.hq.app.claim;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);

    /** The sheet's claims as listed: each person's newest (or most recently reassigned to them) first. */
    List<Claim> findBySheetIdOrderByListedDesc(String sheetId);

    List<Claim> findBySheetIdAndPersonIdOrderByListedDesc(String sheetId, Long personId);

    /** Give a claim the next place in the list, making it the newest of its person's claims. */
    @Modifying(flushAutomatically = true)
    @Query(value = "update claim set listed = next value for claim_listed_seq where id = :id", nativeQuery = true)
    void relist(@Param("id") Long id);

    /** Whether a claim on the sheet carries the reference, compared without regard to case. */
    boolean existsBySheetIdAndRefIgnoreCase(String sheetId, String ref);

    /** Whether a claim on the sheet other than the one given carries the reference, compared without regard to case. */
    boolean existsBySheetIdAndRefIgnoreCaseAndIdNot(String sheetId, String ref, Long id);

    /** The sheet's claims an editor holds locked. */
    List<Claim> findBySheetIdAndLockedByIsNotNull(String sheetId);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /**
     * The last place given in a period sequence on the sheet, counting the places claims left when re-dated
     * into another period; 0 before any.
     */
    @Query(value = "select greatest("
            + "(select coalesce(max(period_seq_number), 0) from claim where sheet_id = :sheetId and period_sequence = :sequence), "
            + "(select coalesce(max(period_seq_number), 0) from claim_retired_number where sheet_id = :sheetId and period_sequence = :sequence))",
            nativeQuery = true)
    int lastInSequence(@Param("sheetId") String sheetId, @Param("sequence") String sequence);

    /** Keep a place a claim leaves in a period sequence, so it is never given again. */
    @Modifying(flushAutomatically = true)
    @Query(value = "insert into claim_retired_number (sheet_id, period_sequence, period_seq_number) "
            + "values (:sheetId, :sequence, :n)", nativeQuery = true)
    void retireNumber(@Param("sheetId") String sheetId, @Param("sequence") String sequence, @Param("n") int n);
}
